import type { RiskResult, BatchCheckItem, ProductsResult, CveDetail, UsageResult } from './models.js';
import { AttestdError, AttestdAPIError, AttestdUnsupportedProductError } from './errors.js';
import {
  DEFAULT_BASE_URL,
  CHECK_PATH,
  BATCH_CHECK_PATH,
  PRODUCTS_PATH,
  CVE_PATH_PREFIX,
  USAGE_PATH,
  RETRY_STATUS_CODES,
  sleep,
  parseCheckResponse,
  parseBatchCheckResponse,
  parseTyposquat,
  buildAttestdError,
  parseProductsResponse,
  parseCveResponse,
  parseUsageResponse,
} from './internal.js';
import type { CachePolicy, SessionStats } from './models.js';
import { ResultCache } from './cache.js';
import { VERSION } from './version.js';

export interface CheckOptions {
  /**
   * When `['cves']`, request per-CVE detail (CVSS, EPSS) on the check response.
   * Default is compact: `cves` is an empty array.
   */
  include?: Array<'cves'>;
}

function wantsCves(options?: CheckOptions): boolean {
  if (!options?.include || options.include.length === 0) {
    return false;
  }
  for (const item of options.include) {
    if (item !== 'cves') {
      throw new AttestdError(
        `attestd: include accepts only 'cves'; got ${JSON.stringify(options.include)}`,
      );
    }
  }
  return true;
}

function normalizeCheckArgs(product: string, version: string): { product: string; version: string } {
  const trimmedProduct = product.trim();
  const trimmedVersion = version.trim();
  if (!trimmedProduct || !trimmedVersion) {
    throw new AttestdError('attestd: product and version are required');
  }
  return { product: trimmedProduct, version: trimmedVersion };
}

function checkUrl(
  baseUrl: string,
  product: string,
  version: string,
  includeCves: boolean,
): string {
  const params = new URLSearchParams({ product, version });
  if (includeCves) params.set('include', 'cves');
  return `${baseUrl}${CHECK_PATH}?${params.toString()}`;
}

function batchUrl(baseUrl: string, includeCves: boolean): string {
  return includeCves
    ? `${baseUrl}${BATCH_CHECK_PATH}?include=cves`
    : `${baseUrl}${BATCH_CHECK_PATH}`;
}

export interface ClientOptions {
  /** Attestd API key (atst_...). Falls back to ATTESTD_API_KEY env var. */
  apiKey?: string;
  /** Override the base URL. Falls back to ATTESTD_BASE_URL env var, then https://api.attestd.io. */
  baseUrl?: string;
  /** Per-request timeout in milliseconds. Defaults to 10 000. */
  timeout?: number;
  /** Maximum retry attempts on 5xx responses. Defaults to 3. */
  maxRetries?: number;
  /**
   * Custom fetch implementation. Defaults to globalThis.fetch.
   * Inject MockFetch / SequentialMockFetch from attestd/testing for unit tests.
   */
  fetch?: typeof globalThis.fetch;
  /**
   * Base delay in ms for exponential backoff between retries. Defaults to 1 000.
   * Set to a small value (e.g. 10) in unit tests to keep retry tests fast.
   */
  retryDelayMs?: number;
  /**
   * Client-side result cache policy. One of "development" (24h), "runtime"
   * (5min, default), "ci" (never expire), or "none" (always hit the API).
   */
  cachePolicy?: CachePolicy;
}

export class Client {
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly timeout: number;
  private readonly maxRetries: number;
  private readonly retryDelayMs: number;
  private readonly fetchImpl: typeof globalThis.fetch;
  private readonly cache: ResultCache;

  constructor(options: ClientOptions = {}) {
    const env = typeof process !== 'undefined' ? process.env : {};
    const apiKey = (options.apiKey ?? env.ATTESTD_API_KEY ?? '').trim();
    if (!apiKey) {
      throw new AttestdError(
        'attestd: apiKey is required. Pass it to Client() or set the ATTESTD_API_KEY environment variable.',
      );
    }
    this.apiKey = apiKey;
    this.baseUrl = (options.baseUrl ?? env.ATTESTD_BASE_URL ?? DEFAULT_BASE_URL).replace(/\/$/, '');
    this.timeout = options.timeout ?? 10_000;
    this.maxRetries = options.maxRetries ?? 3;
    this.retryDelayMs = options.retryDelayMs ?? 1_000;
    this.fetchImpl = options.fetch ?? globalThis.fetch;
    this.cache = new ResultCache(options.cachePolicy ?? 'runtime');
  }

  async check(
    product: string,
    version: string,
    options?: CheckOptions,
  ): Promise<RiskResult> {
    const includeCves = wantsCves(options);
    const args = normalizeCheckArgs(product, version);
    const cached = this.cache.get(args.product, args.version, { includeCves });
    if (cached !== null) {
      return cached;
    }

    const result = await this.fetchCheck(args.product, args.version, includeCves);
    this.cache.put(args.product, args.version, result, { includeCves });
    this.cache.recordApiCall();
    return result;
  }

  /**
   * Drop compact and detailed cached results so the next check() hits the API.
   * Product and version are trimmed to match check() cache keys.
   */
  invalidateCache(product: string, version: string): void {
    const args = normalizeCheckArgs(product, version);
    this.cache.invalidate(args.product, args.version);
  }

  /**
   * Return session observability counters (apiCallsMade, cacheHits, …).
   */
  stats(): SessionStats {
    return this.cache.stats();
  }

  private async fetchCheck(
    product: string,
    version: string,
    includeCves: boolean,
  ): Promise<RiskResult> {
    const url = checkUrl(this.baseUrl, product, version, includeCves);

    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (attempt > 0) {
        await sleep(this.retryDelayMs * Math.pow(2, attempt - 1));
      }

      let response: Response;

      try {
        response = await this.fetchImpl(url, {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${this.apiKey}`,
            'User-Agent': `attestd-js/${VERSION}`,
            Accept: 'application/json',
          },
          signal: AbortSignal.timeout(this.timeout),
        });
      } catch (err) {
        const isTimeout =
          err instanceof Error &&
          (err.name === 'TimeoutError' || err.name === 'AbortError');

        if (isTimeout) {
          throw new AttestdAPIError(
            `Request timed out after ${this.timeout}ms`,
            0,
          );
        }

        lastError = err instanceof Error ? err : new Error(String(err));

        if (attempt < this.maxRetries) continue;

        throw new AttestdAPIError(
          `Network error: ${lastError.message}`,
          0,
        );
      }

      if (response.ok) {
        let data: unknown;
        try {
          data = await response.json();
        } catch {
          throw new AttestdAPIError('Failed to parse Attestd API response as JSON', 200);
        }
        if (
          data &&
          typeof data === 'object' &&
          !Array.isArray(data) &&
          'supported' in data &&
          (data as Record<string, unknown>).supported === false
        ) {
          const typosquat = parseTyposquat((data as Record<string, unknown>).typosquat ?? null);
          throw new AttestdUnsupportedProductError(product, version, typosquat);
        }
        return parseCheckResponse(data, product, version);
      }

      if (!RETRY_STATUS_CODES.has(response.status) || attempt === this.maxRetries) {
        const body = await response.text().catch(() => '');
        throw buildAttestdError(response.status, body, product, version, response.headers);
      }

      await response.text().catch(() => '');

      lastError = new AttestdAPIError(
        `Attestd API returned status ${response.status}`,
        response.status,
      );
    }

    throw lastError ?? new AttestdAPIError('Unknown error', 0);
  }

  async checkBatch(
    items: BatchCheckItem[],
    options?: CheckOptions,
  ): Promise<(RiskResult | null)[]> {
    if (items.length === 0) return [];
    if (items.length > 100) {
      throw new AttestdError(
        `attestd: checkBatch accepts at most 100 items; got ${items.length}`,
      );
    }

    const includeCves = wantsCves(options);
    items = items.map((item) => normalizeCheckArgs(item.product, item.version));
    const results: (RiskResult | null)[] = new Array(items.length).fill(null);
    const missIndices: number[] = [];
    const missItems: BatchCheckItem[] = [];

    for (let i = 0; i < items.length; i++) {
      const item = items[i]!;
      const cached = this.cache.get(item.product, item.version, { includeCves });
      if (cached !== null) {
        results[i] = cached;
      } else {
        missIndices.push(i);
        missItems.push(item);
      }
    }

    if (missItems.length === 0) {
      return results;
    }

    const fetched = await this.fetchBatch(missItems, includeCves);
    this.cache.recordApiCall(missItems.length);

    for (let j = 0; j < missIndices.length; j++) {
      const idx = missIndices[j]!;
      const item = missItems[j]!;
      const result = fetched[j] ?? null;
      results[idx] = result;
      if (result !== null) {
        this.cache.put(item.product, item.version, result, { includeCves });
      }
    }

    return results;
  }

  private async fetchBatch(
    items: BatchCheckItem[],
    includeCves: boolean,
  ): Promise<(RiskResult | null)[]> {
    const url = batchUrl(this.baseUrl, includeCves);
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (attempt > 0) {
        await sleep(this.retryDelayMs * Math.pow(2, attempt - 1));
      }

      let response: Response;

      try {
        response = await this.fetchImpl(url, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${this.apiKey}`,
            'User-Agent': `attestd-js/${VERSION}`,
            Accept: 'application/json',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ items }),
          signal: AbortSignal.timeout(this.timeout),
        });
      } catch (err) {
        const isTimeout =
          err instanceof Error &&
          (err.name === 'TimeoutError' || err.name === 'AbortError');

        if (isTimeout) {
          throw new AttestdAPIError(`Request timed out after ${this.timeout}ms`, 0);
        }

        lastError = err instanceof Error ? err : new Error(String(err));

        if (attempt < this.maxRetries) continue;

        throw new AttestdAPIError(`Network error: ${lastError.message}`, 0);
      }

      if (response.ok) {
        let data: unknown;
        try {
          data = await response.json();
        } catch {
          throw new AttestdAPIError('Failed to parse Attestd batch API response as JSON', 200);
        }
        return parseBatchCheckResponse(data, items);
      }

      if (!RETRY_STATUS_CODES.has(response.status) || attempt === this.maxRetries) {
        const body = await response.text().catch(() => '');
        throw buildAttestdError(response.status, body, '', '', response.headers);
      }

      await response.text().catch(() => '');

      lastError = new AttestdAPIError(
        `Attestd API returned status ${response.status}`,
        response.status,
      );
    }

    throw lastError ?? new AttestdAPIError('Unknown error', 0);
  }

  async products(): Promise<ProductsResult> {
    const data = await this.getWithRetry(PRODUCTS_PATH);
    return parseProductsResponse(data);
  }

  async cve(cveId: string): Promise<CveDetail> {
    const path = `${CVE_PATH_PREFIX}${encodeURIComponent(cveId.trim())}`;
    const data = await this.getWithRetry(path, { cveLookup: true });
    return parseCveResponse(data);
  }

  async usage(): Promise<UsageResult> {
    const data = await this.getWithRetry(USAGE_PATH);
    return parseUsageResponse(data);
  }

  private async getWithRetry(
    path: string,
    options: { cveLookup?: boolean } = {},
  ): Promise<unknown> {
    const url = `${this.baseUrl}${path}`;
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (attempt > 0) {
        await sleep(this.retryDelayMs * Math.pow(2, attempt - 1));
      }

      let response: Response;

      try {
        response = await this.fetchImpl(url, {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${this.apiKey}`,
            'User-Agent': `attestd-js/${VERSION}`,
            Accept: 'application/json',
          },
          signal: AbortSignal.timeout(this.timeout),
        });
      } catch (err) {
        const isTimeout =
          err instanceof Error &&
          (err.name === 'TimeoutError' || err.name === 'AbortError');

        if (isTimeout) {
          throw new AttestdAPIError(`Request timed out after ${this.timeout}ms`, 0);
        }

        lastError = err instanceof Error ? err : new Error(String(err));
        if (attempt < this.maxRetries) continue;
        throw new AttestdAPIError(`Network error: ${lastError.message}`, 0);
      }

      if (response.ok) {
        try {
          return await response.json();
        } catch {
          throw new AttestdAPIError('Failed to parse Attestd API response as JSON', 200);
        }
      }

      if (!RETRY_STATUS_CODES.has(response.status) || attempt === this.maxRetries) {
        const body = await response.text().catch(() => '');
        if (options.cveLookup && response.status === 404) {
          throw new AttestdAPIError('CVE not found', 404);
        }
        if (options.cveLookup && response.status === 400) {
          throw new AttestdAPIError('Invalid CVE id format (expected CVE-YYYY-NNNN)', 400);
        }
        throw buildAttestdError(response.status, body, '', '', response.headers);
      }

      await response.text().catch(() => '');
      lastError = new AttestdAPIError(
        `Attestd API returned status ${response.status}`,
        response.status,
      );
    }

    throw lastError ?? new AttestdAPIError('Unknown error', 0);
  }
}
